@startuml

class Driver {
  + ID : long
  + Name : string
  + isOnSickLeave : boolean
}

class Bus {
  + LicencePlate : string
  + isInRepairShop : boolean
}

class BusRoute {
  + RouteNumber : int
}

class ShiftType {
  + Type : string
}

class Schedule {
  + Date : date
}

class Assignment {
  + Date : date
}

Bus "0..*" -- "0..*" BusRoute : assigned to
Driver "1" -- "0..*" Assignment : assigned to
Bus "1" -- "0..*" Assignment : assigned to
BusRoute "1" -- "0..*" Assignment : has
Assignment "1" -- "1" ShiftType : occurs during

@enduml

